  // find repeating sibling container
  const parent = card.parentElement;
  const pager = document.querySelector(".el-pagination");
  return {
    linkCount: links.length,
    firstHref: links[0].getAttribute("href"),
    ancestors: anc,
    cardTag: card.tagName,
    cardCls: card.className,
    cardCount: document.querySelectorAll("." + String(card.className).split(" ")[0]).length,
    cardText: card.innerText,
    parentCls: parent.className,
    pagerHTML: pager ? pager.outerHTML.replace(/\s+/g, " ").slice(0, 900) : null,
  };
});
