const readCards = async () => {
  const hrefs = await tab.playwright.locator(".content").evaluate((el) =>
    Array.from(el.querySelectorAll(".article a[href^='/articles/']")).map((a) => a.getAttribute("href")));
  const texts = await tab.playwright.locator(".content > .article").allTextContents();
  return hrefs.map((h, i) => {
    const txt = texts[i] || "";
    const lines = txt.split("\n").map((s) => s.trim()).filter(Boolean);
    const m = (lines[0] || "").match(/^【(.+?)】——(.+)$/);
    const school = m ? m[1] : "?";
    const college = m ? m[2] : (lines[0] || "").slice(0, 30);
    const bm = txt.match(/报名时间：([\d-]+)~([\d-]+)/);
